{
    "model": "stable_audio_3_small_sfx", // 固定值；模型 ID
    "task": "audio.generate", // 固定值；音频生成任务
    "input": {
        "prompt": "suspense hallway ambience, distant footsteps echo, cold wind, faint fluorescent light hum, tense unease" // 任意英文描述；想生成的声音
    },
    "parameters": {
        "negative_prompt": "", // 可空；不想要的声音特征
        "duration": 12, // 建议 3-10；音频时长，单位秒
        "steps": 8, // 建议 8-16；推理步数，越高越慢
        "cfg_scale": 1.5, // 建议 1.0-3.0；提示词引导强度
        "seed": -1, // -1 或任意整数；固定可复现，-1 为随机
        "batch_size": 1, // 建议固定 1；批量生成数量
        "truncate_output_to_duration": true // true/false；是否裁剪到指定 duration
    },
    "output": {
        "format": "wav", // 固定 wav；输出格式
        "sample_rate": 44100 // 建议 44100；采样率
    }
}
